#!/usr/bin/env node

/**
 * Generates NPC and location indexes from the root Public markdown source.
 * Output links point at docs/world generated by generate-public-html.js.
 */

const fs = require('fs');
const path = require('path');

const {
  DOCS_DIR,
  PUBLIC_DIR,
  buildPublicPathMap,
  relativeHref,
  toPosix
} = require('./lib/path-map');

const OUTPUT_DIR = path.join(DOCS_DIR, 'data');
const TOOL_PAGE_REL = 'tools/npc-reference.html';

function parseFrontmatter(content) {
  const match = String(content || '').match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return {};

  const data = {};
  let currentKey = null;
  for (const rawLine of match[1].split(/\r?\n/)) {
    const listMatch = rawLine.match(/^\s+-\s+(.*)$/);
    if (listMatch && currentKey) {
      if (!Array.isArray(data[currentKey])) data[currentKey] = [];
      data[currentKey].push(listMatch[1].trim().replace(/^['"]|['"]$/g, ''));
      continue;
    }

    const kvMatch = rawLine.match(/^([A-Za-z0-9_-]+)\s*:\s*(.*)$/);
    if (kvMatch) {
      currentKey = kvMatch[1];
      data[currentKey] = kvMatch[2].trim().replace(/^['"]|['"]$/g, '');
    }
  }
  return data;
}

function pageInfo(entry) {
  const fm = parseFrontmatter(fs.readFileSync(entry.fullPath, 'utf8'));
  const publicParts = toPosix(entry.publicRel).split('/');
  const outputDir = path.posix.dirname(entry.outputRel);

  return {
    ...entry,
    fm,
    name: fm.name || path.posix.basename(entry.publicRel, '.md'),
    type: fm.type || '',
    region: fm.region || (publicParts[0] === 'World' ? publicParts[1] : ''),
    settlement: fm.location || (publicParts[0] === 'World' && publicParts.length > 3 ? publicParts[2] : ''),
    outputDir,
    href: relativeHref(TOOL_PAGE_REL, entry.outputRel),
    file: path.posix.basename(entry.outputRel)
  };
}

function isWorldPage(page) {
  return toPosix(page.publicRel).startsWith('World/');
}

function isNpcPage(page) {
  return page.type === 'NPC' || toPosix(page.publicRel).toLowerCase().includes('/npcs/');
}

function isSettlementPage(page) {
  if (page.type === 'Settlement') return true;
  const parts = toPosix(page.publicRel).split('/');
  if (parts[0] !== 'World' || parts.length !== 4) return false;
  return path.posix.basename(page.publicRel, '.md').toLowerCase() === parts[2].toLowerCase();
}

function isLocationChild(page) {
  if (!isWorldPage(page) || isNpcPage(page) || isSettlementPage(page)) return false;
  const parts = toPosix(page.publicRel).split('/');
  if (parts.length !== 4) return false;
  if (['Groups', 'Events', 'Items', 'Images'].includes(parts[1])) return false;
  return true;
}

function generateNPCIndex(pages) {
  const npcIndex = {};

  for (const page of pages.filter(isNpcPage)) {
    const parts = toPosix(page.publicRel).split('/');
    const npcIdx = parts.findIndex((part) => part.toLowerCase() === 'npcs');
    if (parts[0] !== 'World' || npcIdx < 3) continue;

    const region = page.region || parts[1];
    const settlement = page.settlement || parts[npcIdx - 1];
    if (!region || !settlement) continue;

    if (!npcIndex[region]) npcIndex[region] = {};
    if (!npcIndex[region][settlement]) {
      npcIndex[region][settlement] = {
        basePath: `${relativeHref(TOOL_PAGE_REL, `${page.outputDir}/index-placeholder`).replace(/index-placeholder$/, '')}`,
        npcs: []
      };
    }

    npcIndex[region][settlement].npcs.push({
      name: page.name,
      file: page.file,
      href: page.href
    });
  }

  for (const region of Object.values(npcIndex)) {
    for (const location of Object.values(region)) {
      location.npcs.sort((a, b) => a.name.localeCompare(b.name));
    }
  }

  return npcIndex;
}

function generateLocationIndex(pages) {
  const locationIndex = {};
  const childrenByRegionSettlement = new Map();

  for (const page of pages.filter(isLocationChild)) {
    const parts = toPosix(page.publicRel).split('/');
    const key = `${parts[1]}\u0000${parts[2]}`;
    if (!childrenByRegionSettlement.has(key)) childrenByRegionSettlement.set(key, []);
    childrenByRegionSettlement.get(key).push(page);
  }

  for (const page of pages.filter(isSettlementPage)) {
    const parts = toPosix(page.publicRel).split('/');
    const region = page.region || parts[1];
    const settlement = page.settlement || parts[2] || page.name;
    if (!region || !settlement) continue;

    if (!locationIndex[region]) {
      locationIndex[region] = {
        basePath: relativeHref(TOOL_PAGE_REL, `${path.posix.dirname(path.posix.dirname(page.outputRel))}/index-placeholder`).replace(/index-placeholder$/, ''),
        locations: {}
      };
    }

    const childKey = `${region}\u0000${settlement}`;
    const subLocations = (childrenByRegionSettlement.get(childKey) || [])
      .map((child) => ({
        name: child.name,
        file: child.file,
        href: child.href
      }))
      .sort((a, b) => a.name.localeCompare(b.name));

    locationIndex[region].locations[settlement] = {
      file: page.file,
      href: page.href,
      subLocations
    };
  }

  return locationIndex;
}

function writeJsonFile(outputPath, data) {
  const payload = JSON.stringify(data, null, 2);
  try {
    fs.writeFileSync(outputPath, payload, 'utf8');
    return;
  } catch (error) {
    if (error.code !== 'EPERM' && error.code !== 'EACCES') throw error;
  }

  const tempPath = `${outputPath}.tmp`;
  fs.writeFileSync(tempPath, payload, 'utf8');
  fs.rmSync(outputPath, { force: true });
  fs.renameSync(tempPath, outputPath);
}

function main() {
  console.log('Scanning Public markdown for generated-page indexes...\n');

  const publicMap = buildPublicPathMap(PUBLIC_DIR);
  const pages = publicMap.markdownPages.map(pageInfo);
  const npcIndex = generateNPCIndex(pages);
  const locationIndex = generateLocationIndex(pages);

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });

  const npcOutputPath = path.join(OUTPUT_DIR, 'npc-index.json');
  writeJsonFile(npcOutputPath, npcIndex);

  let totalNPCs = 0;
  Object.values(npcIndex).forEach((region) => {
    Object.values(region).forEach((location) => {
      totalNPCs += location.npcs.length;
    });
  });

  const locationOutputPath = path.join(OUTPUT_DIR, 'location-index.json');
  writeJsonFile(locationOutputPath, locationIndex);

  let totalLocations = 0;
  Object.values(locationIndex).forEach((region) => {
    totalLocations += Object.keys(region.locations).length;
  });

  console.log(`NPC index generated: ${npcOutputPath}`);
  console.log(`  Total NPCs: ${totalNPCs}`);
  console.log(`Location index generated: ${locationOutputPath}`);
  console.log(`  Total locations: ${totalLocations}`);
}

if (require.main === module) {
  main();
}
